mapper.select:
/** * selectVacAprvMngList : isry.couns.mngr.atrzmng.mapper.VacAprvMngMapper : 휴가승인관리목록 조회 */ SELECT AA.COPA_INDEX_SN AS COPA_INDEX_SN /** 번호(상담파티색인일련번호) **/ , COUNT(*) OVER() AS TOTAL_COUNT , CC.FLNM_ENCPT AS APLCNT_NM /** 신청자명 **/ , AA.USER_ID AS APLCNT_ID /** 신청자아이디 **/ , SUBSTR(AA.VCATN_APLY_YMD, 1,4)||'-'||SUBSTR(AA.VCATN_APLY_YMD, 5,2)||'-'||SUBSTR(AA.VCATN_APLY_YMD, 7,2) AS VCATN_APLY_YMD /** 신청일(휴가신청일자) **/ , SUBSTR(AA.VCATN_BGNG_YMD, 1,4)||'-'||SUBSTR(AA.VCATN_BGNG_YMD, 5,2)||'-'||SUBSTR(AA.VCATN_BGNG_YMD, 7,2) AS VCATN_BGNG_YMD /** 휴가시작일 **/ , SUBSTR(AA.VCATN_END_YMD, 1,4)||'-'||SUBSTR(AA.VCATN_END_YMD, 5,2)||'-'||SUBSTR(AA.VCATN_END_YMD, 7,2) AS VCATN_END_YMD /** 휴가종료일 **/ , AA.VCATN_SE_CD AS VCATN_SE_CD /** 휴가유형(휴가구분코드) **/ , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'VCATN_SE_CD' AND A1.CMMNS_CD_VALUE = AA.VCATN_SE_CD ) AS VCATN_SE_CD_NM /** 휴가유형(휴가구분코드이름) **/ , AA.APRV_STTS_SE_CD AS APRV_STTS_SE_CD /** 상태(승인상태구분코드) **/ , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'APRV_STTS_SE_CD' AND A1.CMMNS_CD_VALUE = AA.APRV_STTS_SE_CD ) AS APRV_STTS_SE_CD_NM /** 상태(승인상태구분코드이름) **/ , AA.SMS_SNDNG_YN AS SMS_SNDNG_YN /** 발송상태(SMS발송여부) **/ , DECODE(AA.APRV_STTS_SE_CD,'0','Y','N') AS APRV_YN /** 상태가 대기(1)일 경우 check **/ , CASE WHEN ((AA.APRV_STTS_SE_CD = '2' OR AA.APRV_STTS_SE_CD = '3') AND AA.SMS_SNDNG_YN = 'N') THEN 'Y' ELSE 'N' END AS MSG_YN /** 처리상태가 승인(2) or 반려(3) 이고 문자발송이 N인 경우 check **/ FROM AYC130 AA , SAA200 BB , SCA100 CC WHERE 1=1 AND AA.DEL_YN = 'N' AND AA.USER_ID = BB.USER_ID AND BB.ENFSN_NO = CC.ENFSN_NO(+) /* 종사자번호 */ AND CC.DEL_YN = 'N' /* 종사자 삭제여부 */
AND AA.APRV_STTS_SE_CD = #{aprvSttsSeCd}
AND AA.VCATN_SE_CD = #{vcatnSeCd}
AND AA.USER_ID LIKE '%'||#{userId}||'%'
AND CC.FLNM_ENCPT = #{userNm}
/* * SQL-ID : isry.couns.cmmn.mapper.CounsMapper.cyber_dept_all : 부서 ComboBox 에서 '전체' 선택시 필요한 조건문 */ AND CC.OGDP_DEPT_CD IN ( SELECT DISTINCT(DEPT_CD) FROM SAA300 WHERE INST_NO = '1000000947' AND DEL_YN = 'N' )
AND CC.OGDP_DEPT_CD = #{deptCd}
AND TO_DATE(AA.VCATN_APLY_YMD || '000000', 'YYYYMMDDHH24MISS') >= TO_DATE(#{bgngYmd} || '000000', 'YYYYMMDDHH24MISS')
AND TO_DATE(AA.VCATN_APLY_YMD || '000000', 'YYYYMMDDHH24MISS') < TO_DATE(#{endYmd} || '000000', 'YYYYMMDDHH24MISS')+1
ORDER BY AA.VCATN_APLY_YMD DESC , AA.COPA_INDEX_SN DESC OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY /** 페이징 처리 **/

/** * selectVacAprvMngDetail : isry.couns.mngr.atrzmng.mapper.VacAprvMngMapper : 휴가승인관리 상세 조회 */ SELECT AA.COPA_INDEX_SN AS COPA_INDEX_SN /** 번호(상담파티색인일련번호) **/ , CC.FLNM_ENCPT AS APLCNT_NM /** 신청자명 **/ , AA.USER_ID AS APLCNT_ID /** 신청자아이디 **/ , AA.VCATN_APLY_YMD AS VCATN_APLY_YMD /** 신청일(휴가신청일자) **/ , AA.VCATN_CS_CN AS VCATN_CS_CN /** 신청사유(휴가사유내용) **/ , '15' AS CNSLTNT_USE_PSBLTY_YRYC_DAYCNT /** 연차총일수 **/ , '1' AS CNSLTNT_USE_VCATN_DAYCNT /** 연차사용일수 **/ , AA.VCATN_BGNG_YMD AS VCATN_BGNG_YMD /** 휴가시작일 **/ , AA.VCATN_END_YMD AS VCATN_END_YMD /** 휴가종료일 **/ , TO_CHAR((TO_DATE(AA.VCATN_END_YMD,'YYYYMMDD')-TO_DATE(AA.VCATN_BGNG_YMD,'YYYYMMDD'))+1) AS VAC_PERIOD , AA.PLACE_NM AS PLACE_NM /** 행선지(장소명) **/ , AA.APLCNT_CTTPC_TELNO AS APLCNT_CTTPC_TELNO /** 비상연락처 **/ , AA.RJCT_CS_CN AS RJCT_CS_CN /** 반려사유 **/ , AA.VCATN_SE_CD AS VCATN_SE_CD /** 휴가유형(휴가구분코드) **/ , AA.TASKWK_REPRTS_WRT_TRGT_YN AS TASKWK_REPRTS_WRT_TRGT_YN /** 업무보고서 작성대상 **/ , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'VCATN_SE_CD' AND A1.CMMNS_CD_VALUE = AA.VCATN_SE_CD ) AS VCATN_SE_CD_NM /** 휴가유형(휴가구분코드이름) **/ , AA.APRV_STTS_SE_CD AS APRV_STTS_SE_CD /** 상태(승인상태구분코드) **/ , ( SELECT A1.CMMNS_CD_VALUE_NM FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'APRV_STTS_SE_CD' AND A1.CMMNS_CD_VALUE = AA.APRV_STTS_SE_CD ) AS APRV_STTS_SE_CD_NM /** 상태(승인상태구분코드이름) **/ , AA.SMS_SNDNG_YN AS SMS_SNDNG_YN /** 발송상태(SMS발송여부) **/ FROM AYC130 AA , SAA200 BB , SCA100 CC WHERE 1=1 AND AA.USER_ID = BB.USER_ID AND BB.ENFSN_NO = CC.ENFSN_NO
AND AA.COPA_INDEX_SN = #{copaIndexSn}
AND AA.USER_ID = #{userId}

mapper.update:
/** * updateVacAprvMngBatch : isry.couns.mngr.atrzmng.mapper.VacAprvMngMapper : 휴가승인관리 일괄 승인 */ UPDATE AYC130 AA /** 사이버1388휴가 **/ SET AA.APRV_STTS_SE_CD = '2' /** 승인(2) **/
, AA.LAST_MDFR_ID = #{loginId}
, AA.LAST_MDFCN_DT = SYSDATE WHERE 1=1 AND AA.APRV_STTS_SE_CD IN ('0') /** 대기(0) **/ AND AA.DEL_YN = 'N'

	   /**
        *  updateVacAprvBatch : isry.couns.mngr.atrzmng.mapper.VacAprvMngMapper : selectVacAprvBatchList을 통해 조회된 휴가신청 데이터의 승인상태구분코드를 '대기' → '승인'으로 변경
        */
        UPDATE
                AYC130      T1      /* 사이버1388휴가 */
        SET
                T1.APRV_STTS_SE_CD        =       #{aprvCdValue}
                , T1.LAST_MDFR_ID         =       #{loginId}
                , T1.LAST_MDFCN_DT        =       SYSDATE
        WHERE   1=1
        AND     T1.COPA_INDEX_SN          =       #{COPA_INDEX_SN}

/**
*	updateVacAprvMng : isry.couns.mngr.atrzmng.mapper.VacAprvMngMapper : 휴가승인관리 단건 수정
*/
	UPDATE
			AYC130		AA  /** 사이버1388휴가 **/
	SET
			AA.LAST_MDFR_ID		= #{loginId}
		,	AA.LAST_MDFCN_DT	= SYSDATE


		,	AA.VCATN_APLY_YMD	= #{applyYmd}




		,	AA.VCATN_CS_CN		= #{vacCsCn}




		,	AA.VCATN_SE_CD		= #{vacSeCd}




		,	AA.VCATN_BGNG_YMD	= #{vacBgngYmd}




		,	AA.VCATN_END_YMD	= #{vacEndYmd}




		,	AA.PLACE_NM			= #{placeNm}




		,	AA.APRV_STTS_SE_CD	= #{aprvSttsSeCd}




		,	AA.RJCT_CS_CN		= #{rjctCsCn}




		,	AA.TASKWK_REPRTS_WRT_TRGT_YN	= #{taskwkReprtsWrtTrgtYn}


	WHERE	1=1
		AND	AA.COPA_INDEX_SN	=	#{indexSn}
		AND	AA.DEL_YN			=	'N'
